using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using UnscRelay.Core;
internal static class ErasureRevocationChecks
{
 sealed class Network:HttpMessageHandler{public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellation){Calls++;throw new Exception("Revoked operation reached the network");}}
 public static async Task<int> Run(){var root=Directory.CreateTempSubdirectory("relay-erasure-revocation-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS erasure revocation: "+label);}try{using var contract=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"fixtures/erasure-receipt-contract.json")));var fixture=contract.RootElement;var receipt=fixture.GetProperty("receipt").Deserialize<ErasureReceipt>(VaultSyncCrypto.Json)!;var trust=new ErasureReceiptVerifier(new Dictionary<string,string>{{receipt.KeyId,fixture.GetProperty("publicKey").GetString()!}});var network=new Network();using var client=new CloudAccountClient(root.FullName,network);client.State.Owner=fixture.GetProperty("owner").GetString()!;client.State.Subject=fixture.GetProperty("subject").GetString()!;client.Save();var saved=File.ReadAllBytes(Path.Combine(root.FullName,"account-sync.dpapi"));var notified=0;client.ErasureVerified+=_=>{if(!client.ErasureRevoked)throw new Exception("Deferred revocation flag");try{client.Save();throw new Exception("Observer rewrote revoked state");}catch(OperationCanceledException){notified++;}};
 using(var unsigned=new HttpResponseMessage(HttpStatusCode.Gone){Content=JsonContent.Create(new{error="deleted"})})try{await client.ThrowIfErased(unsigned,CancellationToken.None,trust,DateTimeOffset.FromUnixTimeMilliseconds(fixture.GetProperty("now").GetInt64()));throw new Exception("Unsigned erasure accepted");}catch(OnlineAccessException){Check(!client.ErasureRevoked&&notified==0,"unsigned 410 cannot revoke or authorize local destruction");}
 using(var forged=new HttpResponseMessage(HttpStatusCode.Gone){Content=JsonContent.Create(new{receipt=receipt with{Signature=new string('A',86)}},options:VaultSyncCrypto.Json)})try{await client.ThrowIfErased(forged,CancellationToken.None,trust,DateTimeOffset.FromUnixTimeMilliseconds(fixture.GetProperty("now").GetInt64()));throw new Exception("Forged erasure accepted");}catch(InvalidDataException){Check(!client.ErasureRevoked&&notified==0,"invalid signature never raises a revocation event");}
 using(var valid=new HttpResponseMessage(HttpStatusCode.Gone){Content=JsonContent.Create(new{receipt},options:VaultSyncCrypto.Json)})try{await client.ThrowIfErased(valid,CancellationToken.None,trust,DateTimeOffset.FromUnixTimeMilliseconds(fixture.GetProperty("now").GetInt64()));throw new Exception("Signed erasure was ignored");}catch(AccountErasedOnlineException){Check(client.ErasureRevoked&&notified==1,"verified revocation is atomic before any UI notification callback");}
 var results=await Task.WhenAll(Enumerable.Range(0,2).Select(async _=>{try{await client.AccountDeletionStatus(CancellationToken.None);return false;}catch(OperationCanceledException){return true;}}));Check(results.All(value=>value)&&network.Calls==0,"two concurrent follow-up operations are rejected before network access");Check(File.ReadAllBytes(Path.Combine(root.FullName,"account-sync.dpapi")).SequenceEqual(saved),"revocation prevents account metadata from being saved again");Console.WriteLine("Erasure revocation checks: "+count);return 0;}finally{root.Delete(true);}}
}
